						{ fallbackColor: (text: string) => theme.fg("toolOutput", text) },
						{ maxWidthCells: 60 },
					),
				);
				continue;
			}
			this.#toolImagesContainer.addChild(new Text(theme.fg("toolOutput", `[Image: ${image.mimeType}]`), 1, 0));
		}
	}

